node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Get cart details
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
console.log('=== CART ===');
console.log(JSON.stringify(cart, null, 2));

// Get cart items
const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all('CART-user_58b0a2d6');
console.log('\n=== CART ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get product details for each item
for (const item of items) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(item.product_id);
  if (product) {
    console.log('\n=== PRODUCT for ' + item.cart_item_id + ' ===');
    console.log(JSON.stringify(product, null, 2));
  }
  // Also check rt_variants for pricing
  if (item.variant_id) {
    const variant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(item.variant_id);
    if (variant) {
      console.log('VARIANT:', JSON.stringify(variant, null, 2));
    }
  }
}

db.close();
"
